#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <climits>
#include <algorithm>

using namespace std;

int dim, limit;
vector<vector<int>> capacity;
vector<vector<int>> adj;
vector<int> dist, p;

bool bfs(int source, int sink) {
    fill(dist.begin(), dist.end(), -1);
    queue<int> q;
    q.push(source);
    dist[source] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1 && capacity[u][v] > 0) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return dist[sink] != -1;
}

int dfs(int u, int sink, int flow) {
    if (u == sink) return flow;
    for (int& i = p[u]; i < adj[u].size(); ++i) {
        int v = adj[u][i];
        if (dist[v] == dist[u] + 1 && capacity[u][v] > 0) {
            int f = dfs(v, sink, min(flow, capacity[u][v]));
            if (f > 0) {
                capacity[u][v] -= f;
                capacity[v][u] += f;
                return f;
            }
        }
    }
    return 0;
}

int dinic(int source, int sink) {
    int total = 0;
    while (bfs(source, sink)) {
        fill(p.begin(), p.end(), 0);
        while (int f = dfs(source, sink, INT_MAX)) {
            total += f;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> dim >> limit;

    int total_nodes = 2 * dim * dim + 2;
    capacity.assign(total_nodes, vector<int>(total_nodes, 0));
    adj.resize(total_nodes);

    vector<string> sci(dim), cap(dim);

    int vert[dim][dim][2];
    int bad_pos = -1;

    int next = 2;
    for (int i = 0; i < dim; ++i) {
        cin >> sci[i];
        for (int j = 0; j < dim; ++j) {
            if (sci[i][j] >= '1' && sci[i][j] <= '9') {
                int node = next++;
                capacity[0][node] = sci[i][j] - '0';
                adj[0].push_back(node);
                adj[node].push_back(0);
                vert[i][j][0] = node;
            } else if (sci[i][j] == 'Z') {
                bad_pos = 100 * i + j;
                sci[i][j] = 'Y';
            }
        }
    }

    int max_node = next;
    for (int i = 0; i < dim; ++i) {
        cin >> cap[i];
        for (int j = 0; j < dim; ++j) {
            if (cap[i][j] >= '1' && cap[i][j] <= '9') {
                int node = max_node++;
                capacity[node][1] = cap[i][j] - '0';
                adj[node].push_back(1);
                vert[i][j][1] = node;
            }
        }
    }

    int bad_dist[dim][dim];
    for (int i = 0; i < dim; ++i)
        fill(bad_dist[i], bad_dist[i] + dim, limit + 1);
    if (bad_pos != -1) {
        bad_dist[bad_pos / 100][bad_pos % 100] = 0;
        queue<int> q;
        q.push(bad_pos);
        int dx[] = {1, 0, -1, 0};
        int dy[] = {0, 1, 0, -1};
        while (!q.empty()) {
            int pos = q.front(); q.pop();
            int x = pos / 100, y = pos % 100;
            for (int k = 0; k < 4; ++k) {
                int nx = x + dx[k], ny = y + dy[k];
                if (nx >= 0 && nx < dim && ny >= 0 && ny < dim &&
                    sci[nx][ny] != 'Y' && bad_dist[nx][ny] > bad_dist[x][y] + 1) {
                    bad_dist[nx][ny] = bad_dist[x][y] + 1;
                    q.push(100 * nx + ny);
                }
            }
        }
    }

    for (int i = 0; i < dim; ++i) {
        for (int j = 0; j < dim; ++j) {
            if (sci[i][j] >= '1' && sci[i][j] <= '9') {
                int reach[dim][dim];
                for (int x = 0; x < dim; ++x)
                    fill(reach[x], reach[x] + dim, limit + 1);
                reach[i][j] = 0;

                if (cap[i][j] >= '1' && cap[i][j] <= '9') {
                    int u = vert[i][j][0], v = vert[i][j][1];
                    capacity[u][v] = capacity[v][u] = INT_MAX - 1;
                    adj[u].push_back(v);
                    adj[v].push_back(u);
                }

                queue<int> q;
                q.push(100 * i + j);
                int dx[] = {1, 0, -1, 0};
                int dy[] = {0, 1, 0, -1};
                while (!q.empty()) {
                    int pos = q.front(); q.pop();
                    int x = pos / 100, y = pos % 100;
                    for (int k = 0; k < 4; ++k) {
                        int nx = x + dx[k], ny = y + dy[k];
                        if (nx >= 0 && nx < dim && ny >= 0 && ny < dim &&
                            sci[nx][ny] != 'Y' && reach[nx][ny] > reach[x][y] + 1) {
                            if (cap[nx][ny] >= '1' && cap[nx][ny] <= '9') {
                                if (reach[x][y] + 1 <= bad_dist[nx][ny]) {
                                    int src = vert[i][j][0];
                                    int dst = vert[nx][ny][1];
                                    capacity[src][dst] = INT_MAX - 1;
                                    adj[src].push_back(dst);
                                    adj[dst].push_back(src);
                                }
                            }
                            if (reach[x][y] + 1 < bad_dist[nx][ny]) {
                                reach[nx][ny] = reach[x][y] + 1;
                                q.push(100 * nx + ny);
                            }
                        }
                    }
                }
            }
        }
    }

    cout << dinic(0, 1) << '\n';

    return 0;
}
